        degenerate = hi == lo
        scale = jnp.where(degenerate, 1.0, scale)
        zp = jnp.where(degenerate, 0.0, zp)
        inv = 1.0 / scale
        q = jnp.clip(_round_away(zp + x * inv), -128.0, 127.0)
        q = jnp.where(degenerate, 0.0, q)
        return (q - zp) * scale
