def _same_pad(x, kernel, stride, dilation):
    h, w = x.shape[1], x.shape[2]
    kh, kw = kernel
    sh, sw = stride
    dh, dw = dilation
    out_h = -(-h // sh)
    out_w = -(-w // sw)
    ph = max((out_h - 1) * sh + (kh - 1) * dh + 1 - h, 0)
    pw = max((out_w - 1) * sw + (kw - 1) * dw + 1 - w, 0)
    if ph or pw:
        x = jnp.pad(x, ((0, 0), (ph // 2, ph - ph // 2), (pw // 2, pw - pw // 2), (0, 0)))
    return x


