    y = jnp.matmul(flat, jnp.transpose(w))
    if b is not None:
        y = y + jnp.reshape(b, (1, -1))
    if keep_num_dims:
        y = jnp.reshape(y, x.shape[:-1] + (w.shape[0],))
    return _act(y, act)


